// Turns the hg_settings rows (key/value) into one config object for this run.
const cfg = {};
for (const item of $input.all()) {
  if (item.json && item.json.key) cfg[item.json.key] = item.json.value;
}
if (!cfg.openai_model) throw new Error('hg_settings is empty: run supabase/schema.sql and scripts/setup.py supabase');
cfg.today = new Date().toISOString().slice(0, 10);
return [{ json: cfg }];

// Step 1 of search: turn the plain-English question into structured requirements.
const body = $('Webhook').first().json.body || {};
const cfg = $('Config').first().json;
const role = $('Load Role').all().map(i => i.json).filter(r => r && r.id)[0] || null;
const question = String(body.question || (role && role.search_query) || '').trim().slice(0, 1000);
if (!question) throw new Error('Empty question');

const schema = {
  type: 'object', additionalProperties: false,
  required: ['skills', 'languages', 'location', 'other_requirements', 'semantic_query', 'search_terms'],
  properties: {
    skills: { type: 'array', items: { type: 'object', additionalProperties: false,
      required: ['name', 'synonyms', 'min_years', 'required'],
      properties: { name: { type: 'string' }, synonyms: { type: 'array', items: { type: 'string' } },
        min_years: { type: ['number', 'null'] }, required: { type: 'boolean' } } } },
    languages: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['language', 'required'],
      properties: { language: { type: 'string' }, required: { type: 'boolean' } } } },
    location: { type: ['string', 'null'] },
    other_requirements: { type: 'array', items: { type: 'string' } },
    semantic_query: { type: 'string' },
    search_terms: { type: 'array', items: { type: 'string' } }
  }
};
const system = [
  'Turn a recruiter\'s candidate search into structured requirements.',
  'skills: concrete tools, skills or job functions. Canonical names: GoHighLevel (GHL/HighLevel), QuickBooks Online (QBO), n8n, Zapier,',
  'Make, React, Node.js, TypeScript, AWS, Xero, Gusto, Salesforce, HubSpot, Cold calling, Appointment setting,',
  'Transaction coordination, Calendar management. synonyms: other spellings/abbreviations of the same thing (not related tools).',
  'Alternatives: "X or Y" is ONE skill named X with Y in its synonyms (either one satisfies it). Never list X and Y separately.',
  'required = true unless the recruiter says preferred / nice to have / bonus / ideally. min_years only if a number is given ("3+ years" = 3).',
  'languages: spoken languages mentioned ("speaks Arabic", "bilingual Spanish"). required = true unless "preferred".',
  'other_requirements: anything else (industry like "solar", location, seniority) in short phrases.',
  'search_terms: canonical names + synonyms + languages + key industry words, for keyword matching.',
  'semantic_query: one sentence describing the ideal candidate.'
].join('\n');

return [{
  json: {
    question: question,
    role: role,
    role_id: role ? role.id : null,
    source: body.source || 'api',
    save: body.save !== false,
    openai_body: {
      model: cfg.openai_model, temperature: 0,
      response_format: { type: 'json_schema', json_schema: { name: 'search_request', strict: true, schema: schema } },
      messages: [{ role: 'system', content: system }, { role: 'user', content: question }]
    }
  }
}];

// Reads the parsed requirements and prepares the embedding request + keyword list.
const prev = Object.assign({}, $('Build Parse Prompt').first().json);
delete prev.openai_body;
const cfg = $('Config').first().json;
let parsed;
try {
  parsed = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  throw new Error('Could not parse the question: ' + JSON.stringify($input.first().json).slice(0, 300));
}
const terms = [];
const add = t => {
  t = String(t || '').trim();
  if (t.length > 1 && terms.map(x => x.toLowerCase()).indexOf(t.toLowerCase()) === -1) terms.push(t);
};
(parsed.skills || []).forEach(s => { add(s.name); (s.synonyms || []).forEach(add); });
(parsed.languages || []).forEach(l => add(l.language));
(parsed.search_terms || []).forEach(add);
return [{ json: Object.assign(prev, { parsed: parsed, terms: terms.slice(0, 25),
  embed_body: { model: cfg.embedding_model, input: parsed.semantic_query || prev.question } }) }];

// Step 3: the model scores ONLY the candidates the database returned (it cannot see or invent anyone else).
const q = $('Parse Query').first().json;
const cfg = $('Config').first().json;
const cands = $input.all().map(i => i.json).filter(c => c && c.candidate_id).slice(0, 20);

const schema = {
  type: 'object', additionalProperties: false, required: ['results', 'note'],
  properties: {
    results: { type: 'array', items: { type: 'object', additionalProperties: false,
      required: ['candidate_id', 'score', 'reason_line_1', 'reason_line_2', 'evidence'],
      properties: {
        candidate_id: { type: 'integer' }, score: { type: 'integer' },
        reason_line_1: { type: 'string' }, reason_line_2: { type: 'string' },
        evidence: { type: 'string', description: 'Exact quote copied from this candidate\'s CV text, max 15 words' }
      } } },
    note: { type: 'string' }
  }
};
const system = [
  'You rank candidates for a recruiter. Use ONLY the CV text given for each candidate. Never invent facts or candidates.',
  'Score 0-100: required skills/requirements met = 50, years of experience vs. what was asked = 20,',
  'nice-to-haves and other requirements = 15, language/location fit = 15.',
  'If ANY required item is missing, or below the minimum years asked, the score MUST be below 60.',
  'reason_line_1: why they fit, with concrete numbers (max 20 words). reason_line_2: the main gap or risk, or an extra strength (max 20 words).',
  'evidence: a short exact quote copied character-for-character from that candidate\'s CV text that proves reason_line_1.',
  'Only use candidate_id values from the list. Return at most 8 candidates, best first. Skip clearly irrelevant people.',
  'If nobody fits, return the closest 1-2 with honest low scores.'
].join('\n');
const list = cands.map(c =>
  '### candidate_id: ' + c.candidate_id + '\nName: ' + c.full_name + '\nCV file: ' + c.cv_file_name +
  '\nLocation: ' + (c.location || '?') + '\nLanguages (parsed): ' + JSON.stringify(c.languages) +
  '\nSkills with years (parsed): ' + JSON.stringify(c.skills) + '\nCV TEXT:\n' + String(c.cv_text || '').slice(0, 3500)
).join('\n\n');
const user = 'TODAY: ' + cfg.today + '\nREQUEST: ' + q.question + '\nPARSED REQUIREMENTS: ' + JSON.stringify(q.parsed) +
  (q.role ? '\nROLE: ' + q.role.title + '\nMUST-HAVES: ' + JSON.stringify((q.role.jd || {}).must_haves || []) : '') +
  '\n\nCANDIDATES (' + cands.length + '):\n\n' + (list || '(none)');

return [{
  json: {
    candidate_count: cands.length,
    openai_body: {
      model: cfg.openai_model, temperature: 0,
      response_format: { type: 'json_schema', json_schema: { name: 'ranking', strict: true, schema: schema } },
      messages: [{ role: 'system', content: system }, { role: 'user', content: user }]
    }
  }
}];

// Step 4: deterministic safety net over the model's ranking.
//  - drops any candidate id that is not in the database results (no invented people)
//  - one row per person, every row names its CV file
//  - hard checks: required language (not "basic"), required skill present, minimum years
//  - the evidence quote must really be in that CV
//  Any failed check caps the score below the threshold, so it can't be recommended.
const cfg = $('Config').first().json;
const q = $('Parse Query').first().json;
const parsed = q.parsed || {};
const threshold = Number(cfg.match_threshold || 60);
const cands = $('Search DB').all().map(i => i.json).filter(c => c && c.candidate_id);
const byId = {};
cands.forEach(c => { byId[c.candidate_id] = c; });

let llm;
try {
  llm = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  throw new Error('Ranking returned invalid JSON: ' + JSON.stringify($input.first().json).slice(0, 300));
}

const norm = s => String(s == null ? '' : s).toLowerCase().replace(/\s+/g, ' ').trim();
const flat = s => norm(s).replace(/[^a-z0-9؀-ۿ+.# ]/g, ' ').replace(/\s+/g, ' ').trim();
const WEAK = /(basic|beginner|elementary|\ba1\b|\ba2\b|reading|limited)/i;

function langOk(c, lang) {
  const L = norm(lang);
  const list = c.languages || [];
  if (list.length) return list.some(l => norm(l.language).indexOf(L) !== -1 && !WEAK.test(l.level || ''));
  return norm(c.cv_text).indexOf(L) !== -1;
}
function skillCheck(c, s) {
  const names = [s.name].concat(s.synonyms || []).map(norm).filter(n => n.length > 1);
  let found = false;
  let years = null;
  (c.skills || []).forEach(k => {
    const kn = norm(k.name);
    if (names.some(n => kn.indexOf(n) !== -1 || (kn.length > 2 && n.indexOf(kn) !== -1))) {
      found = true;
      if (typeof k.years === 'number') years = Math.max(years || 0, k.years);
    }
  });
  if (!found) {
    const t = norm(c.cv_text);
    found = names.some(n => t.indexOf(n) !== -1);
  }
  return { found: found, years: years };
}
function evidenceOk(c, ev) {
  const t = flat(c.cv_text);
  const e = flat(ev);
  if (!e) return false;
  if (t.indexOf(e) !== -1) return true;
  const words = e.split(' ').filter(w => w.length > 2);
  if (!words.length) return false;
  return words.filter(w => t.indexOf(w) !== -1).length / words.length >= 0.8;
}

const seen = {};
const dropped = [];
const scored = [];
(llm.results || []).forEach(r => {
  const c = byId[r.candidate_id];
  if (!c) { dropped.push(r.candidate_id); return; }
  if (seen[c.candidate_id]) return;
  seen[c.candidate_id] = true;
  let score = Math.max(0, Math.min(100, Math.round(Number(r.score) || 0)));
  const gaps = [];
  (parsed.languages || []).filter(l => l.required).forEach(l => {
    if (!langOk(c, l.language)) gaps.push('does not speak ' + l.language + ' (fluently)');
  });
  (parsed.skills || []).filter(s => s.required).forEach(s => {
    const k = skillCheck(c, s);
    if (!k.found) gaps.push('no ' + s.name + ' in CV');
    else if (s.min_years && k.years !== null && k.years + 0.05 < s.min_years) gaps.push(k.years + ' yrs ' + s.name + ', needs ' + s.min_years + '+');
  });
  const evOk = evidenceOk(c, r.evidence);
  if (!evOk) gaps.push('quote not found in CV');
  if (gaps.length) score = Math.min(score, threshold - 1);
  scored.push({
    candidate_id: c.candidate_id, cv_id: c.cv_id, cv_file_name: c.cv_file_name,
    name: c.full_name, email: c.email, location: c.location, score: score,
    reason: [r.reason_line_1, r.reason_line_2].map(s => String(s || '').trim()).filter(Boolean).join('\n'),
    evidence: r.evidence, evidence_verified: evOk, gaps: gaps
  });
});
scored.sort((a, b) => b.score - a.score);
const good = scored.filter(s => s.score >= threshold).slice(0, 5);
good.forEach((s, i) => { s.rank = i + 1; });
const closest = scored.filter(s => s.score < threshold).slice(0, 2);
const noMatch = good.length === 0;
const message = noMatch
  ? 'No good match: nobody scored ' + threshold + '+ out of 100.' +
    (closest.length ? ' Closest: ' + closest.map(c => c.name + ' (' + c.score + ', ' + (c.gaps.join('; ') || 'weak fit') + ')').join(' | ') : ' No one in the CV database is close.')
  : 'Top ' + good.length + ' candidate' + (good.length > 1 ? 's' : '');

return [{
  json: {
    question: q.question, role: q.role, role_id: q.role_id, source: q.source, save: q.save,
    parsed: parsed, threshold: threshold, no_match: noMatch, message: message,
    results: good, closest: closest, dropped_ids: dropped, considered: cands.length,
    save_payload: {
      p: {
        question: q.question, role_id: q.role_id, source: q.source, parsed: parsed, no_match: noMatch, message: message,
        results: good.map(g => ({ candidate_id: g.candidate_id, cv_id: g.cv_id, cv_file_name: g.cv_file_name, rank: g.rank,
          score: g.score, reason: g.reason, evidence: g.evidence }))
      }
    }
  }
}];

// Final answer: JSON for the portal/eval + ready-made Slack blocks with Approve buttons.
const g = Object.assign({}, $('Guard & Score').first().json);
delete g.save_payload;
const cfg = $('Config').first().json;
const saved = $input.first().json && $input.first().json.search_id ? $input.first().json : null;
const roles = $('Open Roles').all().map(i => i.json).filter(r => r && r.id);
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const idByCand = {};
if (saved) (saved.items || []).forEach(it => { idByCand[it.candidate_id] = it.shortlist_id; });
g.results.forEach(r => { r.shortlist_id = idByCand[r.candidate_id] || null; });
g.search_id = saved ? saved.search_id : null;

const blocks = [{ type: 'section', text: { type: 'mrkdwn', text: '🔎 *' + esc(g.question) + '*' +
  (g.role ? '\nFor role: *' + esc(g.role.title) + '* (#' + g.role.id + ')' : '') } }];

if (g.no_match) {
  let t = '🤷 *No good match.* Nobody scored ' + g.threshold + '+ out of 100, so I am not recommending anyone.';
  g.closest.forEach(c => {
    t += '\n• Closest: *' + esc(c.name) + '* (' + c.score + '/100): ' + esc(c.gaps.join('; ') || 'weak fit') + ' · 📄 `' + esc(c.cv_file_name) + '`';
  });
  if (!g.closest.length) t += '\nNo one in the CV database is even close.';
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: t.slice(0, 2900) } });
}

g.results.forEach(r => {
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*' + r.rank + '. ' + esc(r.name) + '*  ·  *' + r.score + '/100*\n' +
    esc(r.reason) + '\n📄 CV: `' + esc(r.cv_file_name) + '`').slice(0, 2900) } });
  if (!r.shortlist_id) return;
  const els = [];
  if (g.role) {
    els.push({ type: 'button', style: 'primary', action_id: 'cand_approve', value: String(r.shortlist_id),
      text: { type: 'plain_text', text: '✅ Approve for outreach' } });
  } else if (roles.length) {
    els.push({ type: 'static_select', action_id: 'cand_approve_role', placeholder: { type: 'plain_text', text: '✅ Approve for role…' },
      options: roles.slice(0, 100).map(x => ({ text: { type: 'plain_text', text: ('#' + x.id + ' ' + x.title).slice(0, 75) },
        value: r.shortlist_id + ':' + x.id })) });
  }
  els.push({ type: 'button', action_id: 'cand_reject', value: String(r.shortlist_id), text: { type: 'plain_text', text: '❌ Not a fit' } });
  blocks.push({ type: 'actions', elements: els });
});
if (!g.role && !roles.length && g.results.length) {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'No approved roles yet, so there is nothing to approve these candidates for.' }] });
}
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'Score = must-haves 50 · experience 20 · nice-to-haves 15 · language/location 15. ' +
  'Under ' + g.threshold + ' is never recommended. Only real CVs from the database are used.' +
  (cfg.portal_url ? ' <' + cfg.portal_url + '|Portal>' : '') }] });

g.text = g.no_match ? g.message : g.message + ' for "' + g.question + '"';
g.blocks = blocks.slice(0, 50);
g.ok = true;
return [{ json: g }];
